            {children}
          </div>
          {footer && (
            <div className="mt-auto flex flex-col-reverse gap-2 border-t border-line px-6 py-5 sm:flex-row sm:flex-wrap sm:justify-end sm:gap-3 sm:px-7 [&>.a-button]:w-full sm:[&>.a-button]:w-auto">
