    >
      <input
        ref={input}
        value={q}
        onChange={(e) => {
          setQ(e.target.value);
          setActive(0);
        }}
        aria-label="Search commands"
        role="combobox"
        aria-expanded="true"
        aria-controls="a-command-list"
        aria-activedescendant={
          filtered.length ? "a-command-" + active : undefined
        }
        className="a-input"
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") {
            e.preventDefault();
            setActive((i) => Math.min(i + 1, filtered.length - 1));
          }
          if (e.key === "ArrowUp") {
            e.preventDefault();
            setActive((i) => Math.max(i - 1, 0));
          }
          if (e.key === "Enter" && filtered[active]) {
            filtered[active].onSelect();
            setOpen(false);
          }
        }}
      />
      <ul
        id="a-command-list"
        role="listbox"
        aria-label="Commands"
        className="mt-3"
      >
        {filtered.map((i, n) => (
          <li
            role="option"
            aria-selected={n === active}
            id={"a-command-" + n}
            key={i.label}
            className={
              "cursor-pointer rounded p-3 text-sm " +
              (n === active ? "bg-surface" : "")
            }
            onClick={() => {
              i.onSelect();
              setOpen(false);
            }}
          >
            {i.label}
          </li>
        ))}
      </ul>
      {!filtered.length && (
        <p role="status" className="p-3 text-sm text-muted">
          No commands found.
        </p>
      )}
    </Modal>
  );
}

