          aria-valuetext={text}
          data-state={state}
          className="h-2 w-full overflow-hidden rounded-full bg-surface"
        >
          <div
            data-indeterminate={indeterminate ? "true" : undefined}
            className={cx(
              "a-progress-fill h-full rounded-full transition-[width] duration-(--motion-normal) ease-(--motion-settle) motion-reduce:transition-none",
              fills[tone],
            )}
            style={indeterminate ? undefined : { width: `${percent}%` }}
          />
        </div>
        {description && (
          <p id={descriptionId} className="mt-2 text-xs leading-relaxed text-muted">
            {description}
          </p>
        )}
      </div>
    );
  },
);

/* Progress travels with the component: the indeterminate sweep and its static reduced-motion fallback. */
.a-progress-fill[data-indeterminate="true"] {
  width: 40%;
  animation: a-progress-sweep 1.6s var(--motion-ease, ease-out) infinite;
}
@keyframes a-progress-sweep {
  from { translate: -100% 0; }
  to { translate: 250% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .a-progress-fill[data-indeterminate="true"] {
    width: 100%;
    animation: none;
    translate: 0 0;
    background: repeating-linear-gradient(
      -45deg,
      currentColor 0 6px,
      transparent 6px 12px
    );
    opacity: 0.55;
  }
}

