    if (!node) return true;
    return node.scrollHeight - node.scrollTop - node.clientHeight <= bottomThreshold;
  }, [node]);
  const jumpToLatest = React.useCallback(() => {
    if (!node) return;
    node.scrollTop = node.scrollHeight;
    atBottom.current = true;
    setPending(false);
