          {loading && (
            <p role="status" className="flex items-center justify-center gap-2 py-1 text-xs text-muted">
              <LoaderCircle aria-hidden className="size-4 animate-spin motion-reduce:animate-none" />
              {text.loading}
            </p>
          )}
