      setPending(true);
      setFailed(false);
      (outcome as Promise<void>).then(
        () => {
          if (mounted.current) setPending(false);
        },
        () => {
          if (!mounted.current) return;
          setPending(false);
          setFailed(true);
        },
      );
    }
  };
  if (!q)
    return (
      <p role="status" className="rounded-xl border border-dashed border-line p-6 text-center text-sm text-muted">
        {text.empty}
      </p>
    );
