          <h3 id={uid + "-title"} className="font-editorial text-2xl leading-tight text-ink text-balance">
            {q.title}
            {optional && (
              <span className="ms-2 align-middle font-sans text-xs font-medium tracking-wide text-muted">{text.optional}</span>
            )}
          </h3>
        </div>
