  error?: React.ReactNode;
  /** cards wraps each option in a selectable bordered surface. */
  variant?: "list" | "cards";
  focusRef?: React.Ref<HTMLButtonElement>;
  options: {
    value: string;
    label: React.ReactNode;
    description?: React.ReactNode;
    disabled?: boolean;
  }[];
