          const id = uid + i;
          const optionDescriptionId = o.description ? `${id}-description` : undefined;
          const item = (
            <RG.Item
              ref={i === firstEnabled ? focusRef : undefined}
              id={id}
              value={o.value}
              disabled={o.disabled || props.disabled}
              aria-labelledby={`${id}-label`}
              aria-describedby={optionDescriptionId}
