export function InputOTP({
  length = 6,
  label = "Verification code",
  value,
  onChange,
  disabled,
}: {
  length?: number;
  label?: string;
  value: string;
  onChange: (v: string) => void;
  disabled?: boolean;
}) {
  return (
    <Input
      aria-label={label}
      inputMode="numeric"
      autoComplete="one-time-code"
